insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '5a96e23e-fd51-4336-a092-7721dc9433c3','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','TESTA E CORPO',25,'La testa ed il corpo devono mostrare un uniforme, privo o quasi privo di melanina (meno melanina c''è e meglio è).','Eccessiva melanina sulla testa e sul corpo. Piccole macchie scure sulla testa e sul corpo.',false,false,1,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='TESTA E CORPO');
insert into ob_judging_sheet_fields(template_id,standard_criterion_id,field_code,criterion_name,official_max,sort_order,metadata) select '9ed2d61b-ee85-4824-b2c4-806d0b7e405e',id,'CFPL2023_1',criterion_name,official_max,1,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='TESTA E CORPO' and not exists(select 1 from ob_judging_sheet_fields where template_id='9ed2d61b-ee85-4824-b2c4-806d0b7e405e' and field_code='CFPL2023_1');
insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select 'd0bdd870-9e2f-4184-9c68-01b66e3c4c8b','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','ALI E CODA',20,'Le remiganti devono essere tutte e ben aderenti al corpo. Le punte delle ali devono incontrarsi lungo il centro della schiena. Le penne completamente scure, assolutamente prive di schiarite o orlature. La coda è stretta e ordinata, con tutte le timoniere, dello stesso colore delle ali scure.','Presenza di penne chiare o bianche. Orlature su remiganti e timoniere. Penne anche solo leggermente schiarite. Chiusura incompleta delle ali e coda aperta.',false,false,2,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='ALI E CODA');
insert into ob_judging_sheet_fields(template_id,standard_criterion_id,field_code,criterion_name,official_max,sort_order,metadata) select '9ed2d61b-ee85-4824-b2c4-806d0b7e405e',id,'CFPL2023_2',criterion_name,official_max,2,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='ALI E CODA' and not exists(select 1 from ob_judging_sheet_fields where template_id='9ed2d61b-ee85-4824-b2c4-806d0b7e405e' and field_code='CFPL2023_2');
insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '38d6d75b-c0de-4387-883c-027110ca5da4','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','COPRITRICI',15,'Le penne nascoste maggiori e le alule dell’estremità delle ali devono essere dello stesso colore delle ali. Esse si combinano con i terziari per formare una forma a mezzaluna scura che contrasta con il corpo chiaro.','Profilo irregolare alla mezzaluna. Le piume dell’alula e/o copritrici alari chiare o brizzolate (screziate).',false,false,3,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='COPRITRICI');
insert into ob_judging_sheet_fields(template_id,standard_criterion_id,field_code,criterion_name,official_max,sort_order,metadata) select '9ed2d61b-ee85-4824-b2c4-806d0b7e405e',id,'CFPL2023_3',criterion_name,official_max,3,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='COPRITRICI' and not exists(select 1 from ob_judging_sheet_fields where template_id='9ed2d61b-ee85-4824-b2c4-806d0b7e405e' and field_code='CFPL2023_3');
insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '56e0d2ae-f113-4555-b351-7a0833b488f0','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','COLORE DI FONDO',15,'Il colore deve essere ricco, profondo ed uniforme. I soggetti intensi (jonque) devono mostrare una qualità luminosa, i brinati (mealy) un effetto più morbido e pallido. Il colore bianco deve essere privo di sfumature gialle.','Colore opaco e mancanza di contrasto tra il lipocromo e le melanine.',false,false,4,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='COLORE DI FONDO');
insert into ob_judging_sheet_fields(template_id,standard_criterion_id,field_code,criterion_name,official_max,sort_order,metadata) select '9ed2d61b-ee85-4824-b2c4-806d0b7e405e',id,'CFPL2023_4',criterion_name,official_max,4,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='COLORE DI FONDO' and not exists(select 1 from ob_judging_sheet_fields where template_id='9ed2d61b-ee85-4824-b2c4-806d0b7e405e' and field_code='CFPL2023_4');
insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '3ba9c334-949f-4d07-ad1a-acc3b8d5d05c','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','PIUMAGGIO',10,'Il piumaggio deve essere fine, che forma contorni lisci e fluenti sul corpo, senza alcun accenno di ruvidità o sbuffi.','Piumaggio ruvido e con sbuffi.',false,false,5,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 55, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='PIUMAGGIO');
