insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '679ab625-bc2d-46fb-b1d7-ad421b298fda','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','ZAMPE – UNGHIA E BECCO',5,'Le zampe, le unghie e il becco devono essere più scure possibile.','Zampe pallide e/o unghia bianche. Zampe ed unghia chiare (poca melanina). Becco chiaro.',false,false,6,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 56, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='ZAMPE – UNGHIA E BECCO');
insert into ob_judging_sheet_fields(template_id,standard_criterion_id,field_code,criterion_name,official_max,sort_order,metadata) select '9ed2d61b-ee85-4824-b2c4-806d0b7e405e',id,'CFPL2023_6',criterion_name,official_max,6,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 56, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='ZAMPE – UNGHIA E BECCO' and not exists(select 1 from ob_judging_sheet_fields where template_id='9ed2d61b-ee85-4824-b2c4-806d0b7e405e' and field_code='CFPL2023_6');
insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '649cbbd0-3050-4e9c-a594-6f1bb9faea94','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','TAGLIA',5,'Taglia 13,5 cm con un angolo di 45° Testa larga e spalle larghe sono un pregio.','Taglia inferiore a quella prevista. Testa piccola e spalle strette.',false,false,7,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 56, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='TAGLIA');
