insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '0e4dddc6-69d7-4037-a047-95effe43effa','2ffcf7b2-85f7-47d8-b9eb-372e23f165f4','CONDIZIONI',5,'Deve essere stabile, fiducioso (sicuro di se) e in ottima salute.','Poco stabile e sicuro, in cattive condizioni di salute.',false,false,8,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 56, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='CONDIZIONI');
insert into ob_judging_sheet_fields(template_id,standard_criterion_id,field_code,criterion_name,official_max,sort_order,metadata) select '9ed2d61b-ee85-4824-b2c4-806d0b7e405e',id,'CFPL2023_8',criterion_name,official_max,8,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 56, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 100, "total_conflict": false}'::jsonb from ob_standard_criteria where standard_version_id='2ffcf7b2-85f7-47d8-b9eb-372e23f165f4' and criterion_name='CONDIZIONI' and not exists(select 1 from ob_judging_sheet_fields where template_id='9ed2d61b-ee85-4824-b2c4-806d0b7e405e' and field_code='CFPL2023_8');
insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '4e716b9b-89e0-4045-88b3-dfd8c48be579','0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d','POSIZIONE E STILE',20,'La posizione del corpo forma un angolo di 50° con una linea orizzontale, in completa armonia tra tutti gli arti del corpo. Portamento e Stile armonioso ed elegante che va dalla testa all’estremità della coda formando una linea retta.','Posizione troppo inclinata e con gibbosità. Posizione non eretta. Portamento e Stile apatico, statico e non armonioso.',false,false,1,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 105, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 95, "total_conflict": true}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d' and criterion_name='POSIZIONE E STILE');
