insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select '1ffa7134-15bd-4c98-a658-b5c5c360e55a','0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d','CODA',20,'La lunga coda è in estensione col corpo, e nettamente in linea retta col dorso. L’estremità della larghezza della coda non deve essere inferiore alla larghezza delle spalle.','Coda corta. Coda cadente o rialzata non in linea con il dorso. Coda all’estremità stretta inferiore a quella delle spalle.',false,false,2,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 105, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 95, "total_conflict": true}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d' and criterion_name='CODA');
