insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select 'd29e90c6-8984-4211-8a73-29c0e5a2f03f','0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d','TAGLIA',20,'La taglia complessiva minima è di 21 cm. A parità di pregi sono preferiti i soggetti di taglia superiore.','Taglia inferiore a quella indicata.',false,false,3,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 105, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 95, "total_conflict": true}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d' and criterion_name='TAGLIA');
insert into ob_judging_sheet_fields(template_id,standard_criterion_id,field_code,criterion_name,official_max,sort_order,metadata) select '13cedf72-8651-4ee1-ade9-8ce3bcaa5660',id,'CFPL2023_3',criterion_name,official_max,3,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 105, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 95, "total_conflict": true}'::jsonb from ob_standard_criteria where standard_version_id='0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d' and criterion_name='TAGLIA' and not exists(select 1 from ob_judging_sheet_fields where template_id='13cedf72-8651-4ee1-ade9-8ce3bcaa5660' and field_code='CFPL2023_3');
insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select 'c977652d-8517-4f78-a605-12ba86b5d158','0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d','CORPO – ALI - PIUMAGGIO',15,'Corpo allungato, slanciato con le spalle ben impiantate e attaccate al corpo, senza troppa prominenza sul petto o sulla schiena. Ali lunghe che coprono almeno 1/3 della coda, l’estremità delle ali sono ordinate. Piumaggio attillato completamente liscio e aderente al corpo.','Corpo grossolano, robusto e spigoloso, spalle visibili. Ali corte o incrociate. Piumaggio troppo lungo non aderente al corpo, ruvido e scomposto.',false,false,4,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 105, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 95, "total_conflict": true}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d' and criterion_name='CORPO – ALI - PIUMAGGIO');
