insert into ob_standard_criteria(id,standard_version_id,criterion_name,official_max,ideal,defects,ai_enabled,numeric_scoring_enabled,sort_order,metadata) select 'af4fbe58-75d4-4bfc-827d-5fd28632297c','0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d','TESTA - COLLO',10,'Testa rotonda e leggermente piatta nella parte superiore del cranio e proporzionata al corpo. Becco corto, occhi rotondi senza sopracciglia. Collo ben marcato, né troppo grande né troppo corto.','Testa di forma irregolare, becco grosso. Collo troppo grande o troppo corto. Sopracciglia che non fanno vedere l’occhio.',false,false,5,'{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "pdf_page": 105, "validated_on": "2026-11-27", "scope": "Documented 2023 analytical standard; numerical activation not authorized", "documentary_status": "VERIFIED", "source_total": 95, "total_conflict": true}'::jsonb where not exists(select 1 from ob_standard_criteria where standard_version_id='0e50f134-6a6a-4a5a-9cbb-afd729a1ea1d' and criterion_name='TESTA - COLLO');
